window.RP_SESSION={"id":"S-218c6123c4c0","messages":[{"id":"RP-III-0155678","time":"2026-08-22T22:27:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"아이디어를 얻었다. 대장간에서 쓸 수 있는 얼굴 덮개라.","characters":[]},{"id":"RP-III-0155679","time":"2026-08-22T22:28:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"단순히 물로 적신 천으로 해결 할 수는 없을 것 같다. 아마 열기에 다 말라버리고 말 테니까.","characters":[]},{"id":"RP-III-0155680","time":"2026-08-22T22:28:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"일단 대장간에서 실제로 얼굴로 튀어오르는 것이 무엇인지부터 떠올려보자. 아마...","characters":[]},{"id":"RP-III-0155681","time":"2026-08-22T22:29:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"숯가루, 쇳가루 같은 것이지. 그래.","characters":[]},{"id":"RP-III-0155682","time":"2026-08-22T22:29:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"열기와 연기도 마시게 될 거야. 다만 연기까지 막으면 숨도 못 쉬게 될테니까 넘기자.","characters":[]},{"id":"RP-III-0155683","time":"2026-08-22T22:30:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"호흡을 고려해야 한다. 그래... 어쩌면 얼굴에 달라붙지 않도록 만드는 것이 좋을 수도 있겠다.","characters":[]},{"id":"RP-III-0155684","time":"2026-08-22T22:31:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그럼 쓸만한 것이...","characters":[]},{"id":"RP-III-0155685","time":"2026-08-22T22:32:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"...그렇게 대장간으로 향했다.","characters":[]},{"id":"RP-III-0155686","time":"2026-08-22T22:33:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"...\n\n얇은 쇠막대기를 적당히 반달모양으로 구부린 후 식혀왔다. 얇고 납작하게.","characters":[]},{"id":"RP-III-0155687","time":"2026-08-22T22:33:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"!운명","characters":[]},{"id":"RP-III-0155688","time":"2026-08-22T22:33:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 4 = 4\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-III-0155689","time":"2026-08-22T22:34:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"...내 얼굴 크기엔 잘 맞지 않지만, 별 수 없지.","characters":[]},{"id":"RP-III-0155690","time":"2026-08-22T22:34:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"적어도 브랜의 얼굴엔 잘 들어맞기를 바랄 뿐이다.","characters":[]},{"id":"RP-III-0155691","time":"2026-08-22T22:35:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"의도한 것은 코끝에서 손가락 두 마디쯤 떨어져 설 정도의 규격이었다. 조금 큰대로 만들어보지, 뭐.","characters":[]},{"id":"RP-III-0155692","time":"2026-08-22T22:36:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"거를 것을 씌우자. 천은 안되니까, 양털 펠트를 구해두었다.","characters":[]},{"id":"RP-III-0155693","time":"2026-08-22T22:37:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"둘 다 타는 것은 똑같지만, 적어도 이 쪽은 적실 필요는 없을 것이다.","characters":[]},{"id":"RP-III-0155694","time":"2026-08-22T22:37:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그리고 이것을 그대로 가져다 쓸 생각도 없고 말이다. 가죽도 옆에 가져다 두었는데...","characters":[]},{"id":"RP-III-0155695","time":"2026-08-22T22:41:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"바깥은 무두질한 가죽으로 덮고, 안쪽은 펠트로 채웠다. \n\n코와 덮개의 간격을 유지했고. 또, 가운데 부분의 가죽에 세로로, 길고 얇게 구멍을 내어 호흡이 잘 이루어지도록 의도해 제작했다.","characters":[]},{"id":"RP-III-0155696","time":"2026-08-22T22:42:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"양 볼은 확실히 가죽에 막힐 것이고, 이 얇은 구멍 사이로 불길이 튀는 것만 막으면 되는데, 이제.","characters":[]},{"id":"RP-III-0155697","time":"2026-08-22T22:43:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"글쎄다, 일단 뒷통수와 정수리로 넘겨 묶을 수 있게 가죽 끈을 붙였다.","characters":[]},{"id":"RP-III-0155698","time":"2026-08-22T22:46:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"사진","characters":[]},{"id":"RP-III-0155699","time":"2026-08-22T22:46:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"오래 쓰면 분명 축축해지고, 입을 벌리기도 조금 그렇겠지만 뭐...","characters":[]},{"id":"RP-III-0155700","time":"2026-08-22T22:47:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"일단 이정도로 테스트해보자.","characters":[]},{"id":"RP-III-0155701","time":"2026-08-22T22:47:00+09:00","room":"RP III","name":"인물 미확정 — 브랜의 작업용 덮개를 만든 인물","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-III-0155702","time":"2026-08-22T22:47:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
